mapper.select:
SELECT e.employee_id AS employeeId, e.employee_num AS employeeNum, e.employee_name AS employeeName, o.org_name AS departmentName, p.position_name AS positionName, e.employ_state AS employState FROM employee e LEFT JOIN employee_hr_info h ON e.employee_id = h.employee_id LEFT JOIN organization o ON h.org_id = o.org_id LEFT JOIN hr_position p ON h.position_id = p.position_id
( CAST(e.employee_id AS CHAR) LIKE CONCAT('%', #{keyword}, '%') OR e.employee_num LIKE CONCAT('%', #{keyword}, '%') OR e.employee_name LIKE CONCAT('%', #{keyword}, '%') OR o.org_name LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY e.employ_state = 'WORK' DESC, e.employee_name ASC, e.employee_id ASC LIMIT #{limit} OFFSET #{offset}

