mapper.select:
SELECT id, employee_id, insurance_id, target_month, salary_amount, overtime_amount, meal_amount, total_payment, net_pay, is_finalized, is_sent, national_pension_amount, health_insurance_amount, long_term_care_amount, emp_insurance_amount, income_tax_amount, local_tax_amount, employee_name_snapshot as employeeNameSnapshot, dept_name_snapshot as deptNameSnapshot, position_name_snapshot as positionNameSnapshot, bank_name_snapshot as bankNameSnapshot, account_number_snapshot_enc as accountNumberSnapshotEnc, account_holder_snapshot as accountHolderSnapshot FROM payroll_ledger WHERE target_month = #{targetMonth}
AND employee_name_snapshot LIKE CONCAT('%', #{employeeName}, '%')
AND dept_name_snapshot LIKE CONCAT('%', #{departmentName}, '%')
AND is_finalized = #{isFinalized}
ORDER BY dept_name_snapshot ASC, employee_name_snapshot ASC, id ASC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM payroll_ledger
WHERE target_month = #{targetMonth}

    AND employee_name_snapshot LIKE CONCAT('%', #{employeeName}, '%')


    AND dept_name_snapshot LIKE CONCAT('%', #{departmentName}, '%')


